{
  "category_edits": [
    {
      "category": "network_architecture",
      "rationale": "Add a jointly trained residual bottleneck to each GRU output before the existing history aggregation: h + 0.1 * W2(GELU(W1(h))). This adds nonlinear capacity while preserving embeddings, recurrence, readout, scoring, loss, and optimizer. The generated predictor imports this same model class, so checkpoint loading includes the new layers automatically.",
      "edits": [
        {
          "find": "        self.dropout = nn.Dropout(dropout_rate)\n        with torch.no_grad():",
          "replace": "        self.dropout = nn.Dropout(dropout_rate)\n        bottleneck_units = max(8, hidden_units // 4)\n        self.output_residual = nn.Sequential(\n            nn.Linear(hidden_units, bottleneck_units),\n            nn.GELU(),\n            nn.Linear(bottleneck_units, hidden_units),\n        )\n        with torch.no_grad():"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))\n        out, _ = self.gru(emb)\n        out = self.aggregate_states(out, seq)",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))\n        out, _ = self.gru(emb)\n        out = out + 0.1 * self.output_residual(out)\n        out = self.aggregate_states(out, seq)"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))\n        out, _ = self.gru(emb)\n        out = self.aggregate_states(out, seq)",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))\n        out, _ = self.gru(emb)\n        out = out + 0.1 * self.output_residual(out)\n        out = self.aggregate_states(out, seq)"
        }
      ]
    }
  ],
  "change_summary": "Add the same small residual bottleneck architecture to each independently trained category GRU. Training and prediction use identical transformed states; routing and all training settings remain unchanged."
}
